import { useMemo, useState } from 'react';
import { Button, Card, Stack, Text } from '@jinx-ui/react';

// API @jinx-ui/react здесь принята по умолчанию (Button/Card/Stack/Text, variant/size/onClick).
// Если в вашей версии имена или пропсы другие — правятся импорт и variant, логика не меняется.

type ReportDatePickerProps = {
  value?: Date;
  onChange: (date: Date) => void;
};

const WEEKDAYS = ['Пн', 'Вт', 'Ср', 'Чт', 'Пт', 'Сб', 'Вс'];
const MONTHS = [
  'Январь', 'Февраль', 'Март', 'Апрель', 'Май', 'Июнь',
  'Июль', 'Август', 'Сентябрь', 'Октябрь', 'Ноябрь', 'Декабрь',
];

function startOfDay(date: Date): Date {
  return new Date(date.getFullYear(), date.getMonth(), date.getDate());
}

function addDays(date: Date, amount: number): Date {
  return new Date(date.getFullYear(), date.getMonth(), date.getDate() + amount);
}

function isSameDay(a: Date, b: Date): boolean {
  return (
    a.getFullYear() === b.getFullYear() &&
    a.getMonth() === b.getMonth() &&
    a.getDate() === b.getDate()
  );
}

export default function ReportDatePicker({ value, onChange }: ReportDatePickerProps) {
  const today = useMemo(() => startOfDay(new Date()), []);
  const [internalValue, setInternalValue] = useState<Date>(() => value ?? today);
  const selected = value ?? internalValue;
  const [viewMonth, setViewMonth] = useState<Date>(
    () => new Date(selected.getFullYear(), selected.getMonth(), 1),
  );

  const selectDate = (date: Date) => {
    const next = startOfDay(date);
    setInternalValue(next);
    setViewMonth(new Date(next.getFullYear(), next.getMonth(), 1));
    onChange(next);
  };

  const shiftMonth = (amount: number) => {
    setViewMonth((current) => new Date(current.getFullYear(), current.getMonth() + amount, 1));
  };

  const quickOptions = useMemo(
    () => [
      { label: 'Сегодня', date: today },
      { label: 'Вчера', date: addDays(today, -1) },
      { label: 'Неделя назад', date: addDays(today, -7) },
    ],
    [today],
  );

  const cells = useMemo<(Date | null)[]>(() => {
    const first = new Date(viewMonth.getFullYear(), viewMonth.getMonth(), 1);
    const daysInMonth = new Date(viewMonth.getFullYear(), viewMonth.getMonth() + 1, 0).getDate();
    const leadingBlanks = (first.getDay() + 6) % 7;

    return [
      ...Array.from({ length: leadingBlanks }, () => null),
      ...Array.from(
        { length: daysInMonth },
        (_, index) => new Date(viewMonth.getFullYear(), viewMonth.getMonth(), index + 1),
      ),
    ];
  }, [viewMonth]);

  return (
    <Card>
      <Stack direction="column" gap="var(--jx-space-4)">
        <Stack direction="row" gap="var(--jx-space-2)" wrap>
          {quickOptions.map((option) => (
            <Button
              key={option.label}
              size="sm"
              variant={isSameDay(option.date, selected) ? 'primary' : 'secondary'}
              aria-pressed={isSameDay(option.date, selected)}
              onClick={() => selectDate(option.date)}
            >
              {option.label}
            </Button>
          ))}
        </Stack>

        <Stack direction="row" gap="var(--jx-space-2)" align="center" justify="space-between">
          <Button
            size="sm"
            variant="ghost"
            aria-label="Предыдущий месяц"
            onClick={() => shiftMonth(-1)}
          >
            ‹
          </Button>
          <Text weight="medium">
            {MONTHS[viewMonth.getMonth()]} {viewMonth.getFullYear()}
          </Text>
          <Button
            size="sm"
            variant="ghost"
            aria-label="Следующий месяц"
            onClick={() => shiftMonth(1)}
          >
            ›
          </Button>
        </Stack>

        <div
          role="grid"
          aria-label="Календарь отчёта"
          style={{
            display: 'grid',
            gridTemplateColumns: 'repeat(7, 1fr)',
            gap: 'var(--jx-space-1)',
          }}
        >
          {WEEKDAYS.map((weekday) => (
            <Text key={weekday} size="sm" tone="muted" align="center">
              {weekday}
            </Text>
          ))}

          {cells.map((date, index) =>
            date === null ? (
              <span key={`blank-${index}`} aria-hidden="true" />
            ) : (
              <Button
                key={date.toISOString()}
                size="sm"
                fullWidth
                variant={
                  isSameDay(date, selected)
                    ? 'primary'
                    : isSameDay(date, today)
                      ? 'secondary'
                      : 'ghost'
                }
                aria-pressed={isSameDay(date, selected)}
                aria-label={`${date.getDate()} ${MONTHS[date.getMonth()]} ${date.getFullYear()}`}
                onClick={() => selectDate(date)}
              >
                {date.getDate()}
              </Button>
            ),
          )}
        </div>
      </Stack>
    </Card>
  );
}

